WITH filtered AS (SELECT id, device, browser, started_at, country, CASE WHEN browser IN ('Firefox', 'Edge') THEN 'Tier 1' ELSE 'Other' END AS browser_group, SUBSTRING(browser, 1, 3) AS browser_prefix FROM sessions WHERE customer_id IS NOT NULL AND country IN ('UK', 'TH')), eligible AS (SELECT s.* FROM filtered s WHERE NOT EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.event_type IN ('add_to_cart', 'purchase', 'search'))), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at DESC NULLS LAST, id) AS rank_in_group FROM eligible) x WHERE rank_in_group = 1), with_windows AS (SELECT id, device, ROW_NUMBER() OVER w_recent AS seq_no, FIRST_VALUE(browser, TRUE) OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser, FIRST_VALUE(browser, TRUE) OVER (PARTITION BY browser ORDER BY rank_in_group, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser_2, ROW_NUMBER() OVER (PARTITION BY browser, device ORDER BY started_at DESC, id) AS event_seq, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY browser, country ORDER BY rank_in_group, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser FROM deduped WINDOW w_recent AS (PARTITION BY device ORDER BY rank_in_group DESC, id)), kept AS (SELECT s.* FROM with_windows s WHERE NOT EXISTS (SELECT 1 FROM web_events ch WHERE ch.session_id = s.id AND ch.event_time < '2024-10-12')), eligible_sessions AS (SELECT s.* FROM kept s WHERE NOT EXISTS (SELECT 1 FROM web_events ch WHERE ch.session_id = s.id AND ch.session_id = 35)) SELECT id, device, seq_no, first_known_browser, event_seq FROM eligible_sessions
